/* Banque de questions supplémentaires : mathématiques, chapitres 10, 11, 12, 13, m-reels, m-inequations, m-angles, m-logique, m-didactique */
window.BANK = window.BANK || {};

BANK['maths/10'] = [
  { q: "Un angle de 135° est un angle :", choices: ["aigu", "droit", "obtus", "plat"], answer: 2, expl: "Un angle <b>obtus</b> est compris entre 90° et 180° : c’est le cas de 135°. Repère : aigu &lt; 90° &lt; obtus &lt; 180° (plat)." },
  { q: "Un triangle est rectangle et l’un de ses angles aigus mesure 35°. Combien mesure le troisième angle (en °) ?", answers: ["55", "55°"], expl: "La somme des angles vaut 180° et l’angle droit fait 90° : 180 − 90 − 35 = <b>55°</b>. Astuce : dans un triangle rectangle, les deux angles aigus sont complémentaires (somme 90°)." },
  { q: "Peut-on construire un vrai triangle de côtés 5 cm, 7 cm et 12 cm ?", choices: ["Oui, c’est un triangle quelconque", "Non : 5 + 7 = 12, les trois points sont alignés (triangle aplati)", "Non, car 12 est un nombre pair", "Oui, c’est un triangle rectangle"], answer: 1, expl: "Inégalité triangulaire : le plus grand côté doit être <b>strictement</b> plus petit que la somme des deux autres. Ici 5 + 7 = 12 exactement : le point est sur le segment, on obtient un triangle « aplati »." },
  { q: "ABC est rectangle en A avec AB = 8 cm et AC = 15 cm. Calcule BC (en cm).", answers: ["17", "17 cm"], expl: "D’après Pythagore : BC² = 8² + 15² = 64 + 225 = 289, donc BC = √289 = <b>17 cm</b>. Le piège : oublier de prendre la racine carrée à la fin." },
  { q: "EFG est rectangle en E, avec FG = 25 cm et EF = 7 cm. Calcule EG (en cm).", answers: ["24", "24 cm"], expl: "[FG] est l’hypoténuse (en face de l’angle droit) : FG² = EF² + EG², donc EG² = 625 − 49 = 576 et EG = <b>24 cm</b>. On <b>soustrait</b> quand on cherche un côté de l’angle droit." },
  { type: 'vf', q: "Vrai ou faux : dans un triangle rectangle, l’hypoténuse est toujours le plus grand des trois côtés.", answer: 0, expl: "<b>Vrai</b> : BC² = AB² + AC² est plus grand que AB² et que AC², donc BC est plus grand que chacun des deux autres côtés. Ça permet de vérifier un résultat : une hypoténuse plus courte qu’un autre côté signale une erreur." },
  { q: "Le point M appartient à la médiatrice du segment [AB] et MA = 6 cm. Combien mesure MB (en cm) ?", answers: ["6", "6 cm"], expl: "Tout point de la médiatrice d’un segment est à <b>égale distance</b> de ses extrémités : MB = MA = <b>6 cm</b>." },
  { q: "Un parallélogramme qui a ses quatre côtés de même longueur est forcément un :", choices: ["rectangle", "losange", "trapèze non parallélogramme", "carré"], answer: 1, expl: "Un parallélogramme à 4 côtés égaux est un <b>losange</b>. Ce n’est pas forcément un carré : il faudrait en plus un angle droit." },
  { type: 'vf', q: "Vrai ou faux : un losange est un parallélogramme.", answer: 0, expl: "<b>Vrai</b> : le losange est un parallélogramme particulier (côtés opposés parallèles, diagonales qui se coupent en leur milieu), avec en plus 4 côtés égaux." },
  { type: 'vf', q: "Vrai ou faux : les diagonales d’un rectangle sont toujours perpendiculaires.", answer: 1, expl: "<b>Faux</b> : les diagonales d’un rectangle ont la même longueur, mais elles ne sont perpendiculaires que si le rectangle est un carré. Les diagonales perpendiculaires, c’est la propriété du losange." },
  { q: "Le triangle ABC est inscrit dans un cercle de diamètre [BC]. Que peut-on affirmer ?", choices: ["ABC est rectangle en A", "ABC est rectangle en B", "ABC est équilatéral", "On ne peut rien dire"], answer: 0, expl: "Un triangle inscrit dans un cercle dont un côté est un diamètre est rectangle, et l’angle droit est au sommet <b>opposé au diamètre</b> : ici en A. Le piège : placer l’angle droit sur une extrémité du diamètre." },
  { q: "A, M, B et A, N, C sont alignés dans cet ordre et (MN) // (BC). AM = 2, AB = 6 et MN = 3. Calcule BC.", answers: ["9"], expl: "Thalès : AM/AB = MN/BC, soit 2/6 = 3/BC, donc BC = 3 × 6 ÷ 2 = <b>9</b>. Le grand triangle est un agrandissement de rapport 3 du petit." },
  { q: "A, M, B et A, N, C sont alignés dans cet ordre et (MN) // (BC). AM = 4, AB = 10 et AC = 15. Calcule AN.", answers: ["6"], expl: "AM/AB = AN/AC, soit 4/10 = AN/15, donc AN = 15 × 4 ÷ 10 = <b>6</b>. Pense à toujours mettre les longueurs du petit triangle au numérateur." },
  { q: "A, M, B et A, N, C sont alignés dans cet ordre. AM = 3, AB = 9, AN = 4 et AC = 12. Que peut-on conclure ?", choices: ["(MN) et (BC) sont parallèles", "(MN) et (BC) sont perpendiculaires", "(MN) et (BC) sont sécantes", "On ne peut rien conclure"], answer: 0, expl: "AM/AB = 3/9 = 1/3 et AN/AC = 4/12 = 1/3 : les rapports sont égaux et les points sont dans le même ordre, donc d’après la <b>réciproque de Thalès</b>, (MN) // (BC)." },
  { q: "ABC est rectangle en A. Que vaut tan B ?", choices: ["AB/BC", "AC/BC", "AC/AB", "AB/AC"], answer: 2, expl: "TOA : tan = Opposé ÷ Adjacent. Le côté opposé à B est [AC], le côté adjacent (qui n’est pas l’hypoténuse) est [AB] : tan B = <b>AC/AB</b>." },
  { q: "ABC est rectangle en A, l’angle B mesure 60° et l’hypoténuse BC = 12 cm. Calcule AB (en cm), sachant que cos 60° = 0,5.", answers: ["6", "6 cm"], expl: "[AB] est le côté <b>adjacent</b> à l’angle B : cos B = AB/BC, donc AB = 12 × cos 60° = 12 × 0,5 = <b>6 cm</b>." },
  { q: "EFG est rectangle en E, FG = 13 et EF = 5. Un élève écrit : « EG² = 13² + 5² = 194 ». Quelle est son erreur ?", choices: ["Il s’est trompé dans le calcul de 13²", "Il a traité [EG] comme l’hypoténuse : il fallait soustraire, EG² = 169 − 25", "Il aurait dû utiliser Thalès", "Il n’y a pas d’erreur"], answer: 1, expl: "L’hypoténuse est [FG] (en face de l’angle droit en E). L’élève applique la formule « on additionne » sans identifier l’hypoténuse : il fallait EG² = 169 − 25 = 144, soit EG = 12. Remédiation : toujours repérer d’abord le côté opposé à l’angle droit." },
  { type: 'vf', q: "Vrai ou faux : si BC² ≠ AB² + AC², alors le triangle ABC n’est pas rectangle en A.", answer: 0, expl: "<b>Vrai</b> : c’est la contraposée du théorème de Pythagore. Si le triangle était rectangle en A, l’égalité serait forcément vraie." },
  { q: "Un triangle est isocèle et ses angles à la base mesurent 52°. Combien mesure l’angle au sommet ?", choices: ["76°", "38°", "128°", "52°"], answer: 0, expl: "Les deux angles à la base sont égaux : 180 − 2 × 52 = 180 − 104 = <b>76°</b>. Le piège : ne soustraire qu’une seule fois 52 (on obtiendrait 128°)." },
  { q: "Dans une démonstration rédigée en « On sait que… / Or… / Donc… », que doit contenir la partie « Or » ?", choices: ["Les données de l’énoncé", "La propriété (ou le théorème) utilisée, énoncée en entier", "La conclusion", "Un dessin à main levée"], answer: 1, expl: "« On sait que » = les données ; « Or » = la <b>propriété</b> qui permet de passer des données à la conclusion ; « Donc » = la conclusion. Sans le « Or », le raisonnement n’est pas justifié." }
];

BANK['maths/11'] = [
  { q: "M’ est le symétrique de M par la symétrie axiale d’axe (d). Que représente (d) pour le segment [MM’] ?", choices: ["Sa médiatrice", "Une parallèle à [MM’]", "Une médiane", "Rien de particulier"], answer: 0, expl: "Dans une symétrie axiale, l’axe est la <b>médiatrice</b> de [MM’] : il est perpendiculaire à [MM’] et passe par son milieu (effet « pliage »)." },
  { q: "Combien d’axes de symétrie possède un losange qui n’est pas un carré ?", answers: ["2", "deux"], expl: "Les axes de symétrie d’un losange sont ses <b>2 diagonales</b>. Plie un losange de papier selon une diagonale : les deux moitiés se superposent." },
  { q: "Combien d’axes de symétrie possède un triangle isocèle qui n’est pas équilatéral ?", answers: ["1", "un", "une"], expl: "Un seul axe : la médiatrice de la base, qui passe par le sommet principal. Il en faut 3 seulement si le triangle est équilatéral." },
  { q: "Laquelle de ces figures possède un centre de symétrie mais aucun axe de symétrie ?", choices: ["Un parallélogramme quelconque", "Un triangle isocèle", "Un triangle équilatéral", "Un rectangle"], answer: 0, expl: "Le parallélogramme quelconque a un centre de symétrie (le point d’intersection de ses diagonales) mais <b>aucun axe</b>. Les triangles n’ont jamais de centre de symétrie ; le rectangle a 2 axes." },
  { type: 'vf', q: "Vrai ou faux : un triangle équilatéral possède un centre de symétrie.", answer: 1, expl: "<b>Faux</b> : un triangle équilatéral a 3 axes de symétrie, mais aucun centre. Fais un demi-tour autour de son centre : la pointe du haut se retrouve en bas, la figure ne se superpose pas." },
  { q: "On agrandit une figure d’aire 5 cm² par une homothétie de rapport 2. Quelle est l’aire de la figure obtenue (en cm²) ?", answers: ["20", "20 cm²"], expl: "Les longueurs sont multipliées par 2, donc les aires par 2² = 4 : 5 × 4 = <b>20 cm²</b>. Piège classique : multiplier l’aire par 2 seulement." },
  { q: "Que conserve toujours une homothétie de rapport 3 ?", choices: ["Les longueurs", "Les aires", "Les angles", "Les périmètres"], answer: 2, expl: "Une homothétie conserve les <b>angles</b> (et le parallélisme) : la figure garde sa forme. En revanche, les longueurs et les périmètres sont multipliés par 3, les aires par 9." },
  { type: 'vf', q: "Vrai ou faux : une rotation conserve les aires.", answer: 0, expl: "<b>Vrai</b> : la rotation est une isométrie (comme les symétries et la translation). Elle conserve longueurs, angles, aires, alignement et parallélisme." },
  { q: "Combien de faces possède une pyramide à base pentagonale ?", answers: ["6", "six"], expl: "1 base (le pentagone) + 5 faces latérales triangulaires (une par côté de la base) = <b>6 faces</b>. Vérification avec Euler : 6 faces + 6 sommets − 10 arêtes = 2." },
  { q: "Un polyèdre convexe a 12 faces et 30 arêtes. Combien a-t-il de sommets ?", answers: ["20", "vingt"], expl: "Relation d’Euler : F + S − A = 2, donc 12 + S − 30 = 2 et S = <b>20</b> (c’est le dodécaèdre régulier)." },
  { q: "Lequel de ces solides n’est pas un polyèdre ?", choices: ["Le cône", "Le cube", "Le tétraèdre", "Le prisme à base triangulaire"], answer: 0, expl: "Un polyèdre n’a que des faces <b>planes</b> (des polygones). Le cône a une surface courbe : c’est un solide de révolution, comme le cylindre et la boule." },
  { q: "Un assemblage de 6 carrés comporte 5 carrés alignés et un sixième carré accolé sur le côté. Est-ce un patron de cube ?", choices: ["Oui, toujours", "Non : en pliant, le premier et le cinquième carré de la ligne se superposent", "Non, car il faudrait 8 carrés", "Oui, si le sixième carré est au milieu"], answer: 1, expl: "Une bande de 4 carrés fait déjà le tour du cube : le 5ᵉ carré se pose sur le 1ᵉʳ. Il y a superposition, donc ce n’est <b>jamais</b> un patron de cube." },
  { type: 'vf', q: "Vrai ou faux : tout assemblage de 6 carrés accolés par un côté est un patron de cube.", answer: 1, expl: "<b>Faux</b> : il existe beaucoup d’assemblages de 6 carrés, mais seulement 11 sont des patrons de cube. Par exemple, 5 carrés en ligne ou un bloc de 2 × 2 empêchent le pliage." },
  { q: "Un cylindre a un rayon de 5 cm et une hauteur de 10 cm. Avec π ≈ 3,14, quelle est l’aire du rectangle de son patron (en cm²) ?", answers: ["314", "314 cm²"], expl: "Le rectangle a pour dimensions la hauteur (10 cm) et le périmètre du disque : 2 × π × 5 = 10π ≈ 31,4 cm. Aire ≈ 31,4 × 10 = <b>314 cm²</b>." },
  { q: "Par une translation, l’image d’une droite est :", choices: ["une droite parallèle à la première", "une droite perpendiculaire à la première", "toujours la même droite", "un segment"], answer: 0, expl: "La translation fait « glisser » la figure sans la tourner : la droite image est <b>parallèle</b> à la droite de départ (elle peut être confondue avec elle si on glisse dans sa direction)." },
  { q: "Une réduction de rapport 1/3 multiplie les aires par :", choices: ["1/3", "1/6", "1/9", "1/27"], answer: 2, expl: "Les aires sont multipliées par le carré du rapport : (1/3)² = <b>1/9</b>. Le 1/27 = (1/3)³ concerne les volumes." },
  { q: "M’ est l’image de M par la rotation de centre O et d’angle 90°. On sait que OM = 4 cm. Combien mesure OM’ (en cm) ?", answers: ["4", "4 cm"], expl: "Une rotation fait tourner le point autour du centre en restant sur le <b>cercle</b> de centre O passant par M : OM’ = OM = <b>4 cm</b>." },
  { q: "Paris est située à environ 2° Est. Cette valeur est :", choices: ["sa longitude", "sa latitude", "son altitude", "son fuseau horaire"], answer: 0, expl: "Est/Ouest se rapporte au méridien de Greenwich : c’est la <b>longitude</b>. La latitude se repère en Nord/Sud par rapport à l’équateur (Paris est vers 49° Nord)." },
  { type: 'vf', q: "Vrai ou faux : une latitude peut valoir 120° Nord.", answer: 1, expl: "<b>Faux</b> : la latitude va de 0° (équateur) à 90° (pôle Nord ou pôle Sud). C’est la longitude qui peut aller jusqu’à 180° Est ou Ouest." },
  { q: "Dans un pavé droit muni d’un repère, un point est repéré par son abscisse, son ordonnée et son :", choices: ["altitude", "latitude", "rayon", "diamètre"], answer: 0, expl: "Dans l’espace, il faut <b>3 coordonnées</b> : abscisse, ordonnée et altitude (la « hauteur »). La latitude sert à se repérer sur la sphère terrestre." }
];

BANK['maths/12'] = [
  { q: "Calcule la moyenne de la série : 6 ; 8 ; 10 ; 16.", answers: ["10"], expl: "Somme : 6 + 8 + 10 + 16 = 40 ; effectif : 4. Moyenne = 40 ÷ 4 = <b>10</b>." },
  { q: "Quelle est la médiane de la série : 5 ; 1 ; 8 ; 3 ; 12 ; 7 ?", answers: ["6"], expl: "On range d’abord : 1 ; 3 ; 5 ; 7 ; 8 ; 12. L’effectif (6) est pair : médiane = moyenne des deux valeurs centrales = (5 + 7) ÷ 2 = <b>6</b>." },
  { q: "Dans une classe de 30 élèves, il y a 12 filles. Quelle est la fréquence des filles ?", choices: ["12 %", "40 %", "30 %", "60 %"], answer: 1, expl: "Fréquence = effectif ÷ effectif total = 12 ÷ 30 = 0,4 = <b>40 %</b>. Le piège : confondre l’effectif (12) et la fréquence." },
  { q: "Dans une classe de 24 élèves, 8 viennent à vélo. Dans un diagramme circulaire, quel angle donner au secteur « vélo » (en °) ?", answers: ["120", "120°"], expl: "Fréquence : 8/24 = 1/3. Angle = fréquence × 360° = 360 ÷ 3 = <b>120°</b>." },
  { q: "Trois notes : 10 (coefficient 1), 14 (coefficient 2) et 8 (coefficient 1). Quelle est la moyenne ?", choices: ["10,66…", "11,5", "12", "10,5"], answer: 1, expl: "Moyenne pondérée : (10 × 1 + 14 × 2 + 8 × 1) ÷ (1 + 2 + 1) = 46 ÷ 4 = <b>11,5</b>. Piège : diviser par 3 (le nombre de notes) au lieu de la somme des coefficients." },
  { q: "Dans la série 10 ; 11 ; 12 ; 13 ; 14, on remplace 14 par 54. Quelle affirmation est vraie ?", choices: ["La médiane reste 12 et la moyenne passe de 12 à 20", "La médiane et la moyenne restent égales à 12", "La médiane passe à 13 et la moyenne à 20", "La moyenne reste 12 et la médiane change"], answer: 0, expl: "La valeur centrale ne bouge pas : médiane = 12. La somme passe de 60 à 100, donc la moyenne de 12 à 100 ÷ 5 = 20. La moyenne est <b>sensible aux valeurs extrêmes</b>, pas la médiane." },
  { type: 'vf', q: "Vrai ou faux : une série peut avoir une moyenne de 12 sans qu’aucune de ses valeurs ne soit égale à 12.", answer: 0, expl: "<b>Vrai</b> : par exemple 10 et 14 ont pour moyenne 12. La moyenne est un calcul, pas forcément une valeur de la série." },
  { type: 'vf', q: "Vrai ou faux : la médiane d’une série est toujours l’une des valeurs de la série.", answer: 1, expl: "<b>Faux</b> : avec un effectif pair, on prend la moyenne des deux valeurs centrales. Pour 4 ; 8, la médiane est 6, qui n’est pas dans la série." },
  { q: "On a relevé les tailles des élèves, regroupées en classes (120–130 cm, 130–140 cm…). Quel graphique est adapté ?", choices: ["Un diagramme en bâtons", "Un histogramme", "Une courbe d’évolution", "Un tableau à double entrée"], answer: 1, expl: "Pour des données regroupées <b>en classes</b>, on utilise un histogramme (rectangles accolés). Le diagramme en bâtons convient aux valeurs isolées (nombre de frères et sœurs)." },
  { q: "On lance un dé équilibré à 6 faces. Quelle est la probabilité d’obtenir un multiple de 3 ?", choices: ["1/6", "1/3", "1/2", "2/3"], answer: 1, expl: "Issues favorables : 3 et 6, soit 2 issues sur 6. P = 2/6 = <b>1/3</b>." },
  { q: "On lance un dé équilibré à 6 faces. Quelle est la probabilité d’obtenir un nombre premier ? (fraction ou décimal)", answers: ["1/2", "3/6", "0,5", "0.5"], expl: "Les nombres premiers entre 1 et 6 sont 2, 3 et 5 (1 n’est <b>pas</b> premier). P = 3/6 = <b>1/2</b>." },
  { q: "On lance deux dés équilibrés à 6 faces. Quelle est la probabilité que la somme soit égale à 4 ? (fraction)", answers: ["1/12", "3/36"], expl: "Il y a 36 issues équiprobables. Somme 4 : (1 ; 3), (2 ; 2), (3 ; 1), soit 3 issues. P = 3/36 = <b>1/12</b>. Le piège : oublier que (1 ; 3) et (3 ; 1) sont deux issues différentes." },
  { q: "Une urne contient 3 boules rouges et 2 vertes. On tire une boule, on la remet, puis on en tire une deuxième. Probabilité d’obtenir deux vertes ?", choices: ["4/25", "2/5", "1/10", "4/20"], answer: 0, expl: "Avec remise, la composition ne change pas : P = 2/5 × 2/5 = <b>4/25</b>. Sur un arbre, on multiplie les probabilités le long du chemin." },
  { q: "Même urne (3 rouges, 2 vertes), mais on tire deux boules <b>sans remise</b>. Probabilité d’obtenir deux rouges ?", choices: ["9/25", "3/10", "6/25", "1/2"], answer: 1, expl: "Au 1ᵉʳ tirage : 3/5. Il reste alors 2 rouges sur 4 boules : 2/4. P = 3/5 × 2/4 = 6/20 = <b>3/10</b>. Le piège : garder 3/5 au second tirage (c’est le cas avec remise)." },
  { type: 'vf', q: "Vrai ou faux : après 5 « pile » de suite avec une pièce équilibrée, la probabilité d’obtenir « face » au lancer suivant est plus grande que 1/2.", answer: 1, expl: "<b>Faux</b> : la pièce n’a pas de mémoire, chaque lancer est indépendant : P(face) = 1/2. La loi des grands nombres porte sur un très grand nombre de lancers, pas sur le lancer suivant." },
  { q: "On lance trois pièces de monnaie. Combien y a-t-il d’issues possibles ?", answers: ["8", "huit"], expl: "Chaque pièce donne 2 possibilités : 2 × 2 × 2 = <b>8</b> issues (PPP, PPF, PFP, PFF, FPP, FPF, FFP, FFF). Un arbre permet de n’en oublier aucune." },
  { q: "On lance trois pièces de monnaie. Quelle est la probabilité d’obtenir au moins un « pile » ? (fraction)", answers: ["7/8", "0,875", "0.875"], expl: "Passe par l’événement contraire : « aucun pile » = FFF, de probabilité 1/8. Donc P(au moins un pile) = 1 − 1/8 = <b>7/8</b>." },
  { type: 'vf', q: "Vrai ou faux : si P(A) = 0,35, alors P(non A) = 0,75.", answer: 1, expl: "<b>Faux</b> : P(non A) = 1 − P(A) = 1 − 0,35 = <b>0,65</b>. Attention aux soustractions de décimaux faites trop vite." },
  { q: "Un diagramme en barres montre des ventes de 102, 104 et 106 objets, mais l’axe vertical commence à 100. Quel est le risque ?", choices: ["Aucun, le graphique est exact", "Les écarts paraissent beaucoup plus grands qu’ils ne le sont", "Les valeurs sont fausses", "Les écarts paraissent plus petits"], answer: 1, expl: "Comme l’axe ne commence pas à 0, la barre de 106 semble 3 fois plus haute que celle de 102, alors que l’écart réel est d’environ 4 %. C’est un graphique <b>trompeur</b> : regarde toujours l’origine de l’axe." },
  { q: "Pour la série 7 ; 2 ; 9 ; 4 ; 5, un élève donne 9 comme médiane. Quelle est son erreur ?", choices: ["Il a pris la valeur du milieu sans ranger la série (la médiane est 5)", "Il a calculé la moyenne", "Il a pris la plus grande valeur", "Il n’y a pas d’erreur"], answer: 0, expl: "9 est bien la valeur placée au milieu de la liste… non rangée. Il faut d’abord <b>ranger</b> : 2 ; 4 ; 5 ; 7 ; 9, la médiane est 5. Erreur très fréquente : la médiane exige une série ordonnée." }
];

BANK['maths/13'] = [
  { q: "Lequel de ces exemples est un algorithme ?", choices: ["La technique de la multiplication posée", "Le nombre 254", "Un triangle rectangle", "Le mot « somme »"], answer: 0, expl: "Un algorithme est une <b>suite finie d’instructions</b> pour résoudre un problème. La technique opératoire posée en est un, comme une recette ou un itinéraire." },
  { q: "Programme : « Choisir 6. Soustraire 2. Multiplier le résultat par 5. » Quel est le résultat ?", answers: ["20"], expl: "On suit les étapes dans l’ordre : 6 − 2 = 4, puis 4 × 5 = <b>20</b>. Piège : calculer 2 × 5 d’abord (6 − 10)." },
  { q: "Programme : « Choisir un nombre. Lui ajouter 4. Multiplier le résultat par le nombre de départ. » Quel est le résultat avec −3 ?", answers: ["-3", "−3"], expl: "−3 + 4 = 1, puis 1 × (−3) = <b>−3</b>. En écriture littérale : (x + 4) × x." },
  { q: "Programme : « Choisir x. Multiplier par 4. Ajouter 2. Multiplier le résultat par 3. » Quelle expression donne le résultat ?", choices: ["12x + 6", "12x + 2", "7x + 5", "4x + 6"], answer: 0, expl: "On obtient (4x + 2) × 3 = 12x + <b>6</b> : il faut distribuer le 3 sur les deux termes. Piège : oublier de multiplier le 2." },
  { q: "De combien de degrés le lutin doit-il tourner à chaque sommet pour tracer un dodécagone régulier (12 côtés) ?", answers: ["30", "30°"], expl: "Pour un polygone régulier à n côtés, on tourne de 360 ÷ n : 360 ÷ 12 = <b>30°</b>. C’est l’angle extérieur, pas l’angle intérieur (150°)." },
  { q: "Quand le lutin trace un polygone régulier complet et revient à son orientation de départ, combien vaut la somme de toutes ses rotations ?", choices: ["180°", "360°", "540°", "Cela dépend du nombre de côtés"], answer: 1, expl: "Le lutin fait exactement <b>un tour complet</b> sur lui-même : 360°. C’est pourquoi chaque rotation vaut 360 ÷ n." },
  { q: "mettre x à 3 ; mettre y à 5 ; mettre x à y ; mettre y à x. Quelle est la valeur finale de y ?", answers: ["5", "cinq"], expl: "Trace : x devient 5 (la valeur de y), puis y prend la valeur de x, qui vaut déjà 5 : y = <b>5</b>. Ce programme n’échange pas les valeurs : il faudrait une variable intermédiaire." },
  { q: "En programmation, une variable est :", choices: ["une « boîte » qui porte un nom et contient une valeur qui peut changer", "un nombre qui ne change jamais", "une instruction qui répète un bloc", "un message affiché à l’écran"], answer: 0, expl: "Une variable a un <b>nom</b> et une <b>valeur</b> modifiable (mettre score à 0, ajouter 1 à score). Une valeur fixe est une constante." },
  { type: 'vf', q: "Vrai ou faux : dans une boucle « répéter jusqu’à … », le nombre de tours est fixé à l’avance.", answer: 1, expl: "<b>Faux</b> : la boucle s’arrête quand la condition devient vraie, le nombre de tours dépend donc des valeurs. C’est « répéter 4 fois » qui fixe le nombre de tours." },
  { q: "mettre n à 0 ; répéter jusqu’à n &gt; 10 : ajouter 4 à n. Quelle est la valeur finale de n ?", answers: ["12"], expl: "n vaut 0, puis 4, puis 8 (pas encore &gt; 10), puis <b>12</b> : la condition est vraie, la boucle s’arrête. Piège : s’arrêter à 8 ou répondre 10." },
  { q: "mettre s à 0 ; mettre n à 1 ; répéter 3 fois : ajouter n à s, puis multiplier n par 2. Quelle est la valeur finale de s ?", answers: ["7", "sept"], expl: "Tableau de trace : tour 1 : s = 1, n = 2 ; tour 2 : s = 3, n = 4 ; tour 3 : s = 7, n = 8. Résultat : <b>7</b> (1 + 2 + 4)." },
  { q: "si x &gt; 10 alors dire « grand » sinon dire « petit ». Que dit le lutin avec x = 10 ?", choices: ["grand", "petit", "rien", "grand puis petit"], answer: 1, expl: "10 &gt; 10 est <b>faux</b> (10 n’est pas strictement plus grand que 10), donc on exécute le « sinon » : « petit ». Attention à la différence entre &gt; et ≥." },
  { type: 'vf', q: "Vrai ou faux : « quand drapeau vert cliqué » est un bloc d’événement.", answer: 0, expl: "<b>Vrai</b> : un événement déclenche le script (drapeau vert, touche pressée, clic sur le lutin). Les autres blocs s’exécutent ensuite dans l’ordre." },
  { q: "Pour tracer un triangle équilatéral, un élève écrit : répéter 3 fois : avancer de 100, tourner de 60°. Qu’obtient-il ?", choices: ["Un triangle équilatéral", "Une ligne brisée non fermée (3 côtés d’un hexagone régulier)", "Un carré", "Un segment"], answer: 1, expl: "En tournant de 60°, le lutin ne fait que 180° au total : la figure ne se ferme pas, ce sont 3 côtés d’un hexagone. Il a confondu angle intérieur (60°) et angle de rotation : il fallait <b>120°</b>." },
  { q: "Un programme de calcul semble toujours donner le double du nombre de départ. Comment le prouver ?", choices: ["En le testant avec 3 nombres", "En le testant avec 100 nombres", "En faisant le calcul avec une lettre x", "En demandant à la calculatrice"], answer: 2, expl: "Des exemples, même nombreux, ne prouvent rien en général. Le calcul littéral avec <b>x</b> traite tous les nombres d’un coup : c’est une démonstration." },
  { type: 'vf', q: "Vrai ou faux : un programme Scratch peut contenir une boucle à l’intérieur d’une autre boucle.", answer: 0, expl: "<b>Vrai</b> : ce sont des boucles imbriquées. Par exemple, répéter 3 fois (tracer un carré, puis tourner) dessine une rosace de carrés." },
  { q: "répéter 3 fois { répéter 4 fois { avancer de 50 ; tourner de 90° } ; tourner de 120° }. Combien de fois l’instruction « avancer de 50 » est-elle exécutée ?", answers: ["12", "douze"], expl: "La boucle intérieure s’exécute 4 fois à chacun des 3 tours de la boucle extérieure : 3 × 4 = <b>12</b> (on trace 3 carrés)." },
  { q: "Le lutin se déplace bien en carré mais aucun trait n’apparaît. Quelle est la cause la plus probable ?", choices: ["Il manque « stylo en position d’écriture »", "Il faut tourner de 45°", "La boucle est trop courte", "Le lutin est trop petit"], answer: 0, expl: "Sans le bloc <b>« stylo en position d’écriture »</b>, le lutin bouge sans tracer. C’est une erreur fréquente chez les élèves (et les adultes !)." },
  { type: 'vf', q: "Vrai ou faux : le programme « Choisir un entier. Le multiplier par l’entier qui le suit. » donne toujours un nombre pair.", answer: 0, expl: "<b>Vrai</b> : n et n + 1 sont deux entiers consécutifs, l’un des deux est pair, donc le produit n(n + 1) est pair. Exemple : 7 × 8 = 56." },
  { q: "mettre s à 0 ; répéter 3 fois { ajouter 2 à s ; dire s }. Qu’affiche le lutin ?", choices: ["6 seulement", "2, puis 4, puis 6", "0, puis 2, puis 4", "2 seulement"], answer: 1, expl: "Le bloc « dire s » est <b>à l’intérieur</b> de la boucle : il s’exécute à chaque tour, après l’ajout. On voit 2, 4 puis 6. S’il était après la boucle, on ne verrait que 6." }
];

BANK['maths/m-reels'] = [
  { q: "Quel est le plus petit ensemble de nombres qui contient −12/4 ?", choices: ["ℕ", "ℤ", "𝔻", "ℚ"], answer: 1, expl: "−12/4 = −3 : c’est un entier relatif, donc il est dans <b>ℤ</b>. Piège : s’arrêter à l’écriture fractionnaire et répondre ℚ. Simplifie toujours d’abord !" },
  { q: "Lequel de ces nombres est décimal ?", choices: ["7/20", "1/3", "2/7", "5/6"], answer: 0, expl: "7/20 est irréductible et 20 = 2² × 5 : que des 2 et des 5, donc 7/20 = 0,35 est <b>décimal</b>. Les autres dénominateurs contiennent 3 ou 7." },
  { type: 'vf', q: "Vrai ou faux : 7/12 est un nombre décimal.", answer: 1, expl: "<b>Faux</b> : 7/12 est irréductible et 12 = 2² × 3 contient le facteur 3. Son écriture décimale est illimitée : 0,58333…" },
  { type: 'vf', q: "Vrai ou faux : 21/28 est un nombre décimal.", answer: 0, expl: "<b>Vrai</b> : il faut d’abord simplifier ! 21/28 = 3/4 = 0,75. Le 7 du dénominateur disparaît avec la simplification. On ne regarde le dénominateur que sur la fraction <b>irréductible</b>." },
  { q: "Écris 0,121212… sous forme de fraction irréductible.", answers: ["4/33"], expl: "x = 0,1212… ; 100x = 12,1212… ; 100x − x = 12, donc 99x = 12 et x = 12/99 = <b>4/33</b> (on simplifie par 3)." },
  { q: "Écris 2,333… sous forme de fraction irréductible.", answers: ["7/3"], expl: "x = 2,333… ; 10x = 23,333… ; 9x = 21, donc x = 21/9 = <b>7/3</b>. Vérification : 7 ÷ 3 = 2,333…" },
  { q: "L’écriture décimale de 1/7 est périodique. Combien de chiffres comporte sa période ?", answers: ["6", "six"], expl: "1/7 = 0,142857 142857… : la période est 142857, soit <b>6 chiffres</b>. Dans la division par 7, il y a au plus 6 restes non nuls, donc la période a au plus 6 chiffres." },
  { q: "Le nombre √50 est :", choices: ["un entier", "un décimal non entier", "un rationnel non décimal", "un irrationnel"], answer: 3, expl: "50 n’est pas un carré parfait (7² = 49, 8² = 64), donc √50 est <b>irrationnel</b> (√50 = 5√2 ≈ 7,07…)." },
  { q: "Quel est le plus petit ensemble de nombres qui contient √0,25 ?", choices: ["ℕ", "ℤ", "𝔻", "ℝ seulement"], answer: 2, expl: "√0,25 = 0,5 car 0,5² = 0,25. C’est un <b>décimal</b> : 𝔻. Piège : croire qu’une racine carrée est toujours irrationnelle." },
  { type: 'vf', q: "Vrai ou faux : la somme de deux nombres irrationnels est toujours irrationnelle.", answer: 1, expl: "<b>Faux</b> : un seul contre-exemple suffit : √2 + (−√2) = 0, qui est rationnel." },
  { type: 'vf', q: "Vrai ou faux : tout entier relatif est un nombre rationnel.", answer: 0, expl: "<b>Vrai</b> : ℤ ⊂ ℚ. Par exemple −5 = −5/1 est le quotient de deux entiers." },
  { q: "Dans la démonstration de l’irrationalité de √2 (par l’absurde), où se trouve la contradiction ?", choices: ["p et q sont tous deux pairs, alors que p/q était supposée irréductible", "p² est négatif", "√2 est plus grand que 2", "q vaut 0"], answer: 0, expl: "On suppose √2 = p/q <b>irréductible</b>, et on montre que p et q sont pairs : on pourrait alors simplifier par 2. C’est absurde, donc √2 n’est pas rationnel." },
  { q: "Donne l’écriture décimale de 7/16.", answers: ["0,4375", "0.4375"], expl: "16 = 2⁴, donc l’écriture est finie. 7/16 = 7 × 625 / 10 000 = <b>0,4375</b> (ou division posée : 7 ÷ 16)." },
  { q: "Quel nombre est compris strictement entre 1,41 et 1,42 ?", choices: ["√2", "√3", "1,4", "141/100"], answer: 0, expl: "√2 ≈ 1,414… est bien entre 1,41 et 1,42. √3 ≈ 1,73 ; 1,4 est trop petit ; 141/100 = 1,41 n’est pas <b>strictement</b> supérieur à 1,41." },
  { q: "Écris 0,8333… (le 3 se répète) sous forme de fraction irréductible.", answers: ["5/6"], expl: "x = 0,8333… ; 100x = 83,333… et 10x = 8,333… En soustrayant : 90x = 75, donc x = 75/90 = <b>5/6</b>. Quand la période ne commence pas tout de suite, on soustrait 10x et non x." },
  { q: "Lequel de ces nombres est rationnel ?", choices: ["(√2)²", "√6", "π + 1", "√8"], answer: 0, expl: "(√2)² = 2 par définition de la racine carrée : c’est un entier, donc un <b>rationnel</b>. Les trois autres sont irrationnels." },
  { q: "Laquelle de ces inclusions est fausse ?", choices: ["ℕ ⊂ ℤ", "ℤ ⊂ 𝔻", "𝔻 ⊂ ℤ", "ℚ ⊂ ℝ"], answer: 2, expl: "On a ℕ ⊂ ℤ ⊂ 𝔻 ⊂ ℚ ⊂ ℝ. <b>𝔻 ⊂ ℤ</b> est faux : 0,5 est décimal mais pas entier." },
  { q: "Combien d’entiers naturels sont strictement compris entre −3,5 et 2,7 ?", answers: ["3", "trois"], expl: "Les entiers naturels sont positifs ou nuls : 0, 1 et 2 conviennent, soit <b>3</b>. Piège : compter −3, −2, −1, qui sont des entiers relatifs mais pas naturels." },
  { q: "Un élève affirme : « 1/3 = 0,33, donc 1/3 est un nombre décimal. » Que lui réponds-tu ?", choices: ["Il a raison", "0,33 n’est qu’une valeur approchée : 1/3 = 0,333… a une écriture illimitée, il n’est pas décimal", "1/3 est irrationnel", "1/3 n’est pas un nombre"], answer: 1, expl: "0,33 × 3 = 0,99 ≠ 1 : ce n’est qu’une <b>approximation</b>. 1/3 est rationnel mais pas décimal, car son dénominateur contient le facteur 3." },
  { q: "Écris 1,25 sous forme de fraction irréductible.", answers: ["5/4"], expl: "1,25 = 125/100, et on simplifie par 25 : <b>5/4</b>. Vérification : 5 ÷ 4 = 1,25." }
];

BANK['maths/m-inequations'] = [
  { q: "Résous 3x − 4 &lt; 11. Les solutions sont x &lt; …", answers: ["5"], expl: "3x &lt; 11 + 4, soit 3x &lt; 15, puis x &lt; <b>5</b> (on divise par 3, positif : le sens ne change pas)." },
  { q: "Résous −5x &gt; 20.", choices: ["x &gt; −4", "x &lt; −4", "x &gt; 4", "x &lt; 4"], answer: 1, expl: "On divise par −5, un nombre <b>négatif</b> : on change le sens. x &lt; −4. Vérification avec x = −5 : −5 × (−5) = 25 &gt; 20 ✔." },
  { q: "Résous 2x + 7 ≥ 5x − 8.", choices: ["x ≥ 5", "x ≤ 5", "x ≤ −5", "x ≥ −5"], answer: 1, expl: "2x − 5x ≥ −8 − 7, soit −3x ≥ −15. On divise par −3 en changeant le sens : x ≤ <b>5</b>. Vérification avec x = 0 : 7 ≥ −8 ✔." },
  { q: "Quel est le plus grand nombre entier solution de 4x − 3 &lt; 17 ?", answers: ["4", "quatre"], expl: "4x &lt; 20, donc x &lt; 5. L’inégalité est <b>stricte</b> : 5 n’est pas solution, le plus grand entier est <b>4</b>." },
  { q: "Quel est le plus petit nombre entier solution de −2x + 1 ≤ 9 ?", answers: ["-4", "−4"], expl: "−2x ≤ 8, puis on divise par −2 en changeant le sens : x ≥ −4. −4 est solution (inégalité large), c’est donc le plus petit entier : <b>−4</b>." },
  { type: 'vf', q: "Vrai ou faux : 0 est solution de 3x − 2 &gt; x + 1.", answer: 1, expl: "<b>Faux</b> : on remplace x par 0 : 3 × 0 − 2 = −2 et 0 + 1 = 1. Or −2 &gt; 1 est faux. (Les solutions sont x &gt; 1,5.)" },
  { type: 'vf', q: "Vrai ou faux : les inéquations x &gt; 3 et −x &lt; −3 ont les mêmes solutions.", answer: 0, expl: "<b>Vrai</b> : en multipliant −x &lt; −3 par −1, on change le sens et on obtient x &gt; 3. Les deux inéquations sont équivalentes." },
  { q: "Sur une droite graduée, comment représente-t-on les solutions de x &lt; 2 ?", choices: ["On colore à gauche de 2, avec un crochet ouvert en 2 (2 exclu)", "On colore à droite de 2, avec un crochet fermé", "On colore à gauche de 2, avec un crochet fermé (2 inclus)", "On marque seulement le point 2"], answer: 0, expl: "Les solutions sont les nombres <b>plus petits</b> que 2 (à gauche), et 2 n’est pas solution car l’inégalité est stricte : crochet tourné vers l’extérieur (ouvert)." },
  { q: "Un élève résout −3x &lt; 9 et écrit « x &lt; −3 ». Quelle est son erreur ?", choices: ["Il a mal divisé 9 par 3", "Il a divisé par un nombre négatif sans changer le sens de l’inégalité", "Il aurait dû soustraire 3", "Il n’y a pas d’erreur"], answer: 1, expl: "En divisant par −3, il faut changer le sens : la bonne réponse est x &gt; −3. Vérification avec x = 0 : −3 × 0 = 0 &lt; 9, donc 0 est solution, ce qui contredit « x &lt; −3 »." },
  { q: "Pour lire graphiquement l’image de 3 par une fonction f, on part :", choices: ["de 3 sur l’axe des abscisses, on rejoint la courbe et on lit l’ordonnée", "de 3 sur l’axe des ordonnées, on rejoint la courbe et on lit l’abscisse", "de l’origine du repère", "du point d’intersection de la courbe avec l’axe des ordonnées"], answer: 0, expl: "L’image se lit sur l’axe <b>vertical</b> : on part de 3 sur l’axe horizontal (abscisses), on monte jusqu’à la courbe, on lit l’ordonnée f(3). La démarche inverse (partir de l’axe vertical) donne les antécédents." },
  { type: 'vf', q: "Vrai ou faux : un nombre peut avoir plusieurs antécédents par une fonction.", answer: 0, expl: "<b>Vrai</b> : la droite horizontale peut couper la courbe en plusieurs points (ou aucun). Par exemple, avec f(x) = x², 4 a deux antécédents : 2 et −2." },
  { type: 'vf', q: "Vrai ou faux : un nombre peut avoir plusieurs images par une fonction.", answer: 1, expl: "<b>Faux</b> : une fonction associe à chaque nombre <b>une seule</b> image. Une verticale ne coupe jamais la courbe d’une fonction en deux points." },
  { q: "Graphiquement, les solutions de f(x) &gt; 2 sont :", choices: ["les abscisses des points de la courbe situés au-dessus de la droite horizontale d’ordonnée 2", "les ordonnées des points situés au-dessus de 2", "les abscisses supérieures à 2", "les points d’intersection de la courbe avec l’axe des abscisses"], answer: 0, expl: "On trace la droite horizontale y = 2 et on repère les morceaux de courbe <b>au-dessus</b>. Les solutions sont leurs <b>abscisses</b> (une inéquation en x a pour solutions des valeurs de x)." },
  { q: "Salle de sport : formule A à 12 € la séance ; formule B : abonnement de 90 € puis 3 € la séance. À partir de combien de séances B est-elle strictement moins chère ?", answers: ["11", "onze"], expl: "B moins chère si 90 + 3x &lt; 12x, soit 90 &lt; 9x, donc x &gt; 10. Pour 10 séances les deux coûtent 120 € ; B devient strictement moins chère à partir de <b>11</b> séances." },
  { q: "Location de voiture : A coûte 50 € + 0,20 € par km ; B coûte 0,45 € par km. Quand A est-elle strictement plus avantageuse ?", choices: ["Pour moins de 200 km", "Pour plus de 200 km", "Pour exactement 200 km", "Jamais"], answer: 1, expl: "A moins chère si 50 + 0,2x &lt; 0,45x, soit 50 &lt; 0,25x, donc x &gt; 200. À 200 km, les deux coûtent 90 €. Le forfait n’est rentable qu’au-delà de <b>200 km</b>." },
  { q: "Une formule « 8 € d’inscription puis 2 € par séance » est modélisée, pour x séances, par :", choices: ["f(x) = 8x + 2", "f(x) = 2x + 8", "f(x) = 10x", "f(x) = 2(x + 8)"], answer: 1, expl: "Le prix par séance multiplie x, l’inscription s’ajoute une seule fois : f(x) = <b>2x + 8</b>. C’est une fonction affine (droite qui ne passe pas par l’origine)." },
  { q: "Quelle est l’abscisse du point d’intersection des droites d’équations y = 4x et y = 2x + 10 ?", answers: ["5"], expl: "Au point d’intersection, les ordonnées sont égales : 4x = 2x + 10, donc 2x = 10 et x = <b>5</b> (le point est (5 ; 20))." },
  { q: "Résous −1 ≤ 2x + 3 &lt; 7.", choices: ["−2 ≤ x &lt; 2", "−1 ≤ x &lt; 7", "−2 &lt; x ≤ 2", "−4 ≤ x &lt; 4"], answer: 0, expl: "On soustrait 3 aux trois membres : −4 ≤ 2x &lt; 4, puis on divise par 2 (positif, les sens restent) : <b>−2 ≤ x &lt; 2</b>." },
  { q: "Résous x/3 − 1 ≥ 2. Les solutions sont x ≥ …", answers: ["9"], expl: "x/3 ≥ 3, puis on multiplie par 3 (positif) : x ≥ <b>9</b>." },
  { q: "Quelles sont les solutions de 2x + 1 &gt; 2x + 3 ?", choices: ["x &gt; 1", "Tous les nombres réels", "Aucun nombre", "x &gt; −1"], answer: 2, expl: "En soustrayant 2x des deux côtés, on obtient 1 &gt; 3, ce qui est toujours faux : l’inéquation n’a <b>aucune solution</b>. Graphiquement, ce sont deux droites parallèles, l’une toujours sous l’autre." }
];

BANK['maths/m-angles'] = [
  { q: "Deux angles sont complémentaires et de même mesure. Combien mesure chacun d’eux (en °) ?", answers: ["45", "45°"], expl: "Complémentaires : la somme vaut 90°. Deux angles égaux : 90 ÷ 2 = <b>45°</b>. Ne confonds pas avec supplémentaires (180°)." },
  { q: "Deux droites sécantes forment un angle de 35°. Combien mesurent les trois autres angles ?", choices: ["35°, 145° et 145°", "145°, 145° et 145°", "35°, 35° et 55°", "55°, 125° et 55°"], answer: 0, expl: "L’angle opposé par le sommet est égal : 35°. Les deux autres sont supplémentaires de 35° (ils forment un angle plat avec lui) : 180 − 35 = <b>145°</b>. Total : 35 + 145 + 35 + 145 = 360° ✔." },
  { q: "Deux droites sont coupées par une sécante. Deux angles correspondants sont :", choices: ["du même côté de la sécante, l’un entre les deux droites et l’autre à l’extérieur", "de part et d’autre de la sécante, tous deux entre les droites", "de part et d’autre de la sécante, tous deux à l’extérieur", "opposés par le sommet"], answer: 0, expl: "Correspondants = « à la même place » sur chaque droite : du même côté de la sécante, l’un à l’intérieur, l’autre à l’extérieur. La deuxième proposition décrit les <b>alternes-internes</b>." },
  { type: 'vf', q: "Vrai ou faux : deux droites coupées par une sécante forment des angles alternes-internes de 70° et 72° ; elles sont parallèles.", answer: 1, expl: "<b>Faux</b> : pour conclure au parallélisme, les angles alternes-internes doivent être <b>égaux</b>. Ici 70° ≠ 72°, donc les droites sont sécantes (même si elles semblent parallèles sur le dessin)." },
  { type: 'vf', q: "Vrai ou faux : deux angles adjacents sont toujours supplémentaires.", answer: 1, expl: "<b>Faux</b> : adjacents signifie seulement « même sommet, un côté commun, de part et d’autre ». Deux angles adjacents de 20° et 30° ne font que 50°." },
  { q: "Quelle est la somme des angles d’un heptagone convexe (7 côtés), en degrés ?", answers: ["900", "900°"], expl: "Formule : (n − 2) × 180° = (7 − 2) × 180 = 5 × 180 = <b>900°</b>. On découpe l’heptagone en 5 triangles depuis un sommet." },
  { q: "Combien mesure chaque angle d’un décagone régulier (10 côtés), en degrés ?", answers: ["144", "144°"], expl: "Somme : (10 − 2) × 180 = 1 440°. Les 10 angles sont égaux : 1 440 ÷ 10 = <b>144°</b>." },
  { q: "La somme des angles d’un polygone convexe vaut 1 080°. Combien a-t-il de côtés ?", choices: ["6 (hexagone)", "7 (heptagone)", "8 (octogone)", "10 (décagone)"], answer: 2, expl: "(n − 2) × 180 = 1 080, donc n − 2 = 6 et n = <b>8</b> : c’est un octogone." },
  { q: "Pour démontrer que la somme des angles d’un triangle vaut 180°, on trace la parallèle à un côté passant par le sommet opposé. Quelle propriété utilise-t-on ensuite ?", choices: ["Des droites parallèles forment avec une sécante des angles alternes-internes égaux", "Le théorème de Pythagore", "Les angles opposés par le sommet sont égaux", "La médiatrice est à égale distance des extrémités"], answer: 0, expl: "Les deux angles à la base se « reportent » au sommet grâce aux <b>alternes-internes</b> égaux (droites parallèles). Avec l’angle du sommet, ils forment un angle plat : 180°." },
  { q: "A(−3 ; 8) et B(7 ; 2). Quelle est l’abscisse du milieu de [AB] ?", answers: ["2"], expl: "Abscisse du milieu = moyenne des abscisses : (−3 + 7) ÷ 2 = 4 ÷ 2 = <b>2</b>. (L’ordonnée serait (8 + 2) ÷ 2 = 5.)" },
  { q: "Dans un repère, le point A(−2 ; 5) est situé :", choices: ["à gauche de l’axe des ordonnées et au-dessus de l’axe des abscisses", "à droite de l’axe des ordonnées et au-dessus de l’axe des abscisses", "à gauche de l’axe des ordonnées et en dessous de l’axe des abscisses", "sur l’axe des abscisses"], answer: 0, expl: "On lit d’abord l’<b>abscisse</b> (−2 : vers la gauche), puis l’<b>ordonnée</b> (5 : vers le haut). Piège classique : inverser l’ordre des coordonnées." },
  { q: "M(4 ; 5) est le milieu de [AB], avec A(1 ; 2). Quelle est l’abscisse de B ?", answers: ["7"], expl: "(1 + x_B) ÷ 2 = 4, donc 1 + x_B = 8 et x_B = <b>7</b>. Astuce : de A à M on avance de 3, de M à B on avance encore de 3." },
  { q: "Pour construire la médiatrice de [AB] au compas, pourquoi faut-il un rayon plus grand que la moitié de AB ?", choices: ["Sinon les deux arcs ne se coupent pas", "Pour que la médiatrice soit plus longue", "Parce que le compas ne peut pas être plus petit", "Ce n’est pas nécessaire"], answer: 0, expl: "Avec un rayon inférieur à AB/2, les deux arcs centrés en A et en B ne se rencontrent pas : impossible d’obtenir les deux points d’intersection par lesquels passe la <b>médiatrice</b>." },
  { q: "Pour construire un hexagone régulier inscrit dans un cercle de rayon 4 cm, quelle longueur reporte-t-on 6 fois sur le cercle ?", choices: ["4 cm", "2 cm", "6 cm", "8 cm"], answer: 0, expl: "L’hexagone régulier est formé de 6 triangles équilatéraux : son côté est égal au <b>rayon</b> du cercle, soit 4 cm." },
  { type: 'vf', q: "Vrai ou faux : on ne peut pas construire au compas un triangle de côtés 3 cm, 4 cm et 8 cm car les arcs ne se coupent pas.", answer: 0, expl: "<b>Vrai</b> : 3 + 4 = 7 &lt; 8. Les arcs de rayons 3 cm et 4 cm centrés aux extrémités d’un segment de 8 cm ne se rencontrent pas : l’inégalité triangulaire n’est pas respectée." },
  { q: "Laquelle de ces consignes est correctement rédigée pour un programme de construction ?", choices: ["Trace le cercle de centre O et de rayon 3 cm.", "Fais un rond de 3 autour de O.", "Le cercle est là où il y a O.", "Tracer un truc rond de rayon 3."], answer: 0, expl: "Un programme de construction utilise des phrases courtes, à l’<b>impératif</b>, avec le vocabulaire exact (centre, rayon, segment, cercle) et les mesures avec leurs unités." },
  { type: 'vf', q: "Vrai ou faux : dans le plan, deux droites perpendiculaires à une même troisième droite sont parallèles entre elles.", answer: 0, expl: "<b>Vrai</b> : c’est la propriété utilisée pour tracer une parallèle avec l’équerre et la règle (deux perpendiculaires successives)." },
  { q: "Dans un triangle ABC, l’angle A mesure 50° et l’angle extérieur en C (formé avec le prolongement de [BC]) mesure 130°. Combien mesure l’angle B (en °) ?", answers: ["80", "80°"], expl: "L’angle C du triangle est supplémentaire de l’angle extérieur : 180 − 130 = 50°. Puis B = 180 − 50 − 50 = <b>80°</b>. On remarque que l’angle extérieur (130°) = A + B." },
  { q: "Dans un quadrillage de type bataille navale, « B3 » désigne :", choices: ["une case (colonne B, ligne 3)", "une longueur de 3 unités", "un angle", "un déplacement de 3 cases"], answer: 0, expl: "En bataille navale, on repère une <b>case</b> par sa colonne (lettre) et sa ligne (chiffre). C’est une première étape avant le repère où l’on repère des points (nœuds) par des coordonnées." },
  { q: "Pour construire au compas la perpendiculaire à (d) passant par M, on place deux points I et J de (d) tels que MI = MJ, puis on trace la médiatrice de [IJ]. Pourquoi passe-t-elle par M ?", choices: ["Parce que M est à égale distance de I et de J", "Parce que M est le milieu de [IJ]", "Parce que (d) est parallèle à [IJ]", "Parce que l’angle IMJ est droit"], answer: 0, expl: "La médiatrice de [IJ] est l’ensemble des points <b>équidistants</b> de I et de J : M en fait partie. Et une médiatrice est perpendiculaire au segment, donc à (d)." }
];

BANK['maths/m-logique'] = [
  { q: "Un restaurant propose 4 entrées, 3 plats et 5 desserts. Combien de menus « entrée + plat + dessert » différents ?", answers: ["60", "soixante"], expl: "Principe multiplicatif : 4 × 3 × 5 = <b>60</b> menus. Un arbre montrerait 4 branches, puis 3 sur chacune, puis 5." },
  { q: "Combien de mots de passe formés de 2 lettres (de A à Z, répétition autorisée) suivies d’un chiffre (0 à 9) ?", answers: ["6760", "6 760"], expl: "26 possibilités pour chaque lettre et 10 pour le chiffre : 26 × 26 × 10 = <b>6 760</b>." },
  { q: "De combien de façons peut-on ranger 6 livres différents sur une étagère ?", answers: ["720"], expl: "6 choix pour la 1ʳᵉ place, 5 pour la 2ᵉ, etc. : 6 × 5 × 4 × 3 × 2 × 1 = <b>720</b>." },
  { q: "8 coureurs participent à une course. Combien de podiums différents (or, argent, bronze) sont possibles ?", answers: ["336"], expl: "8 choix pour l’or, puis 7 pour l’argent, puis 6 pour le bronze : 8 × 7 × 6 = <b>336</b>. L’ordre compte ici, donc on ne divise pas." },
  { q: "Combien de diagonales possède un hexagone ?", choices: ["6", "9", "12", "15"], answer: 1, expl: "Chaque sommet est relié par une diagonale aux 3 sommets non voisins : 6 × 3 = 18, mais chaque diagonale est comptée deux fois : 18 ÷ 2 = <b>9</b>. Même raisonnement que pour les poignées de main." },
  { q: "Combien de codes à 4 chiffres (de 0 à 9) peut-on former si les 4 chiffres sont tous différents ?", answers: ["5040", "5 040"], expl: "10 choix, puis 9, puis 8, puis 7 : 10 × 9 × 8 × 7 = <b>5 040</b>. Avec répétition, on aurait 10 000 codes." },
  { q: "Avec les chiffres 1, 3 et 5 (répétition autorisée), combien de nombres de 2 chiffres peut-on écrire ?", choices: ["6", "9", "8", "3"], answer: 1, expl: "3 choix pour le chiffre des dizaines et 3 pour celui des unités : 3 × 3 = <b>9</b> (11, 13, 15, 31, 33, 35, 51, 53, 55). Le 6 oublie les doublons 11, 33, 55." },
  { q: "La réciproque de « Si un triangle est équilatéral, alors il est isocèle » est :", choices: ["vraie", "fausse : un triangle d’angles 40°, 70°, 70° est isocèle sans être équilatéral", "fausse, car la propriété de départ est fausse", "identique à la propriété de départ"], answer: 1, expl: "Réciproque : « Si un triangle est isocèle, alors il est équilatéral ». Elle est <b>fausse</b> : un contre-exemple suffit. La propriété de départ, elle, est vraie." },
  { q: "Quelle est la contraposée de « Si n est un multiple de 10, alors n est pair » ?", choices: ["Si n est pair, alors n est un multiple de 10", "Si n est impair, alors n n’est pas un multiple de 10", "Si n n’est pas un multiple de 10, alors n est impair", "n est un multiple de 10 et n est impair"], answer: 1, expl: "Contraposée de « A ⇒ B » : « non B ⇒ non A ». Non pair = impair, donc « si n est impair, n n’est pas multiple de 10 ». La 1ʳᵉ proposition est la réciproque, la 3ᵉ est fausse (n = 4)." },
  { type: 'vf', q: "Vrai ou faux : une propriété et sa contraposée sont toujours vraies ou fausses en même temps.", answer: 0, expl: "<b>Vrai</b> : elles sont logiquement équivalentes. C’est pourquoi on peut démontrer une propriété en démontrant sa contraposée." },
  { type: 'vf', q: "Vrai ou faux : si une propriété est vraie, sa réciproque est forcément vraie.", answer: 1, expl: "<b>Faux</b> : « si c’est un carré, il a 4 côtés égaux » est vrai, mais la réciproque est fausse (le losange). C’est la contraposée qui est toujours équivalente, pas la réciproque." },
  { q: "Avoir quatre angles droits est une condition … pour être un carré.", choices: ["suffisante mais pas nécessaire", "nécessaire mais pas suffisante", "nécessaire et suffisante", "ni nécessaire ni suffisante"], answer: 1, expl: "Tout carré a 4 angles droits : c’est <b>nécessaire</b>. Mais un rectangle non carré aussi : ce n’est pas <b>suffisant</b>. Dans « carré ⇒ 4 angles droits », la conclusion est la condition nécessaire." },
  { q: "Laquelle de ces équivalences (« si et seulement si ») est vraie ?", choices: ["Un quadrilatère est un parallélogramme ⇔ ses diagonales se coupent en leur milieu", "Un nombre est pair ⇔ il est multiple de 4", "Un quadrilatère a 4 côtés égaux ⇔ c’est un carré", "x² = 9 ⇔ x = 3"], answer: 0, expl: "La propriété des diagonales du parallélogramme et sa réciproque sont vraies : c’est une <b>équivalence</b>. Contre-exemples pour les autres : 6 est pair mais pas multiple de 4 ; le losange ; x = −3." },
  { q: "Comment prouver que « la somme de deux nombres impairs est toujours paire » ?", choices: ["En vérifiant sur 3 + 5 = 8", "En vérifiant sur 50 exemples", "En écrivant (2a + 1) + (2b + 1) = 2(a + b + 1)", "C’est impossible à prouver"], answer: 2, expl: "Pour une affirmation <b>générale</b>, il faut une démonstration avec des lettres : 2(a + b + 1) est un multiple de 2, donc pair. Les exemples illustrent mais ne prouvent pas." },
  { type: 'vf', q: "Vrai ou faux : pour tout entier naturel n, le nombre n² + 1 est impair.", answer: 1, expl: "<b>Faux</b> : un contre-exemple suffit. Pour n = 1, n² + 1 = 2, qui est pair (c’est même le cas pour tout n impair)." },
  { q: "« Tout nombre impair supérieur à 1 est premier. » Donne le plus petit contre-exemple.", answers: ["9", "neuf"], expl: "3, 5 et 7 sont premiers, mais <b>9</b> = 3 × 3 ne l’est pas. Un seul contre-exemple suffit pour montrer que l’affirmation est fausse." },
  { type: 'vf', q: "Vrai ou faux : le carré d’un nombre décimal positif est toujours plus grand que ce nombre.", answer: 1, expl: "<b>Faux</b> : 0,5² = 0,25, qui est plus petit que 0,5. C’est vrai pour les nombres supérieurs à 1, mais pas entre 0 et 1." },
  { q: "Combien existe-t-il de nombres entiers de 3 chiffres (de 100 à 999) ?", answers: ["900"], expl: "Le premier chiffre ne peut pas être 0 (9 choix), les deux autres oui (10 choix chacun) : 9 × 10 × 10 = <b>900</b>. Vérification : 999 − 100 + 1 = 900." },
  { q: "En CE1, pour dénombrer les tenues possibles avec 2 pantalons et 3 pulls, quel outil aide le mieux les élèves à ne rien oublier ?", choices: ["Un arbre ou un tableau à double entrée", "La formule n × (n − 1)", "Deviner puis vérifier", "La calculatrice"], answer: 0, expl: "À l’école, on organise la recherche avec une <b>liste organisée</b>, un <b>arbre</b> ou un <b>tableau à double entrée</b> : chaque case du tableau 2 × 3 est une tenue (6 en tout)." },
  { q: "Quelle est la négation de « Tous les élèves ont rendu leur devoir » ?", choices: ["Aucun élève n’a rendu son devoir", "Au moins un élève n’a pas rendu son devoir", "Tous les élèves ont oublié leur devoir", "Un seul élève a rendu son devoir"], answer: 1, expl: "Pour que « tous » soit faux, il suffit d’<b>un seul</b> élève qui n’a pas rendu son devoir. « Aucun » est beaucoup plus fort : c’est le piège classique (comme le contre-exemple qui réfute une affirmation générale)." }
];

BANK['maths/m-didactique'] = [
  { q: "Une situation-problème est une tâche :", choices: ["que l’élève peut commencer avec ses connaissances, mais dont la solution experte nécessite le savoir visé", "que l’élève sait déjà résoudre parfaitement", "réservée à l’évaluation finale", "dont l’enseignant donne la méthode avant de commencer"], answer: 0, expl: "L’élève peut <b>s’engager</b> avec ce qu’il sait, mais ses procédures sont coûteuses ou insuffisantes : le nouveau savoir apparaît alors comme l’outil efficace." },
  { q: "Comment appelle-t-on, chez Brousseau, le moment où l’élève accepte de prendre en charge le problème posé ?", answers: ["dévolution", "la dévolution", "devolution"], expl: "La <b>dévolution</b> : l’enseignant « remet » le problème à l’élève, qui s’en sent responsable. À ne pas confondre avec l’institutionnalisation (l’enseignant dit ce qu’il faut retenir)." },
  { q: "Dans un problème de partage, l’enseignant décide d’autoriser ou non l’usage de jetons. Il agit sur :", choices: ["une variable didactique", "le contrat didactique", "un obstacle", "l’institutionnalisation"], answer: 0, expl: "La présence ou non du matériel change les <b>procédures</b> des élèves (manipuler et distribuer, ou calculer) : c’est une variable didactique, au même titre que la taille des nombres." },
  { q: "Un élève de CM1 range : 3,7 &lt; 3,25 &lt; 3,125. Quelle remédiation est la plus pertinente ?", choices: ["Écrire 3,700 ; 3,250 ; 3,125, utiliser le tableau de numération et la droite graduée", "Lui faire recopier la bonne réponse dix fois", "Lui dire de toujours prendre le nombre qui a le plus de chiffres", "Passer à la leçon suivante"], answer: 0, expl: "L’élève applique la règle des entiers (« plus de chiffres = plus grand »). Il faut redonner du <b>sens</b> aux chiffres : 7 dixièmes = 70 centièmes = 700 millièmes, et placer les nombres sur une droite graduée." },
  { q: "La méthode dite « de Singapour » s’appuie sur la progression :", choices: ["concret → imagé → abstrait", "abstrait → imagé → concret", "imagé → abstrait → concret", "abstrait seulement, avec beaucoup d’entraînement"], answer: 0, expl: "On part de la <b>manipulation</b> (concret), puis de schémas (imagé, comme le schéma en barres), avant les écritures mathématiques (abstrait)." },
  { type: 'vf', q: "Vrai ou faux : il est recommandé de pratiquer le calcul mental environ 15 minutes par jour à l’école élémentaire.", answer: 0, expl: "<b>Vrai</b> : le calcul mental doit être <b>quotidien</b>, en séances courtes et régulières (environ 15 minutes), pour automatiser et développer des stratégies." },
  { q: "Le procédé La Martinière consiste à :", choices: ["faire écrire la réponse sur une ardoise et la faire montrer par tous en même temps", "corriger les cahiers le soir", "interroger un seul élève au tableau", "faire réciter les tables en chœur"], answer: 0, expl: "Avec l’<b>ardoise</b> levée au signal, l’enseignant voit d’un coup d’œil toutes les réponses : chaque élève est actif et les erreurs sont repérées immédiatement." },
  { q: "Savoir par cœur que 7 × 8 = 56 relève :", choices: ["du calcul automatisé", "du calcul réfléchi", "du calcul posé", "du calcul instrumenté"], answer: 0, expl: "Un résultat <b>mémorisé</b> (tables, compléments à 10, doubles) relève du calcul automatisé. Le calcul réfléchi mobilise une stratégie (par exemple 7 × 8 = 7 × 10 − 7 × 2)." },
  { type: 'vf', q: "Vrai ou faux : le calcul 98 + 45 = 100 + 45 − 2 relève du calcul automatisé.", answer: 1, expl: "<b>Faux</b> : arrondir 98 à 100 puis compenser est une <b>stratégie</b> : c’est du calcul réfléchi. Le calcul automatisé, c’est un résultat restitué directement de mémoire." },
  { q: "Un problème qui nécessite plusieurs étapes de calcul est appelé problème :", choices: ["basique", "complexe", "atypique", "ouvert"], answer: 1, expl: "On distingue les problèmes <b>basiques</b> (une seule étape), <b>complexes</b> (plusieurs étapes, combinaison de problèmes basiques) et <b>atypiques</b> (recherche, logique)." },
  { q: "Comment qualifie-t-on un problème de recherche ou de logique, pour lequel l’élève ne dispose pas d’une procédure connue ?", answers: ["atypique", "atypiques", "problème atypique", "un problème atypique"], expl: "Un problème <b>atypique</b> demande de chercher, d’essayer, d’organiser ses essais : il développe le raisonnement plus que la technique." },
  { q: "Un élève de CE1 écrit « 3004 » sous la dictée de « trois-cent-quatre ». Quelle hypothèse sur son erreur est la plus probable ?", choices: ["Il juxtapose l’écriture de « trois cents » (300) et celle de « quatre » (4) : il transcrit l’oral sans maîtriser la valeur positionnelle", "Il ne connaît pas le chiffre 4", "Il a mal entendu", "Il confond addition et multiplication"], answer: 0, expl: "L’élève écrit « ce qu’il entend » : 300 puis 4. Il ne comprend pas encore que, dans 304, le 0 indique l’absence de dizaines. C’est une erreur de <b>numération</b>, pas d’inattention." },
  { q: "Quelle remédiation proposer à cet élève qui écrit « 3004 » pour « trois-cent-quatre » ?", choices: ["Faire représenter le nombre avec du matériel (3 plaques de cent, 0 barre de dix, 4 cubes) puis le placer dans un tableau C / D / U", "Lui faire recopier 304 vingt fois", "Lui interdire d’écrire des zéros", "Lui donner une calculatrice"], answer: 0, expl: "On revient au <b>sens</b> : manipuler (centaines, dizaines, unités), verbaliser (« 3 centaines, 0 dizaine, 4 unités »), puis écrire dans le tableau de numération : on voit que le nombre n’a que 3 chiffres." },
  { type: 'vf', q: "Vrai ou faux : en raison du contrat didactique, les élèves pensent souvent qu’il faut utiliser tous les nombres de l’énoncé.", answer: 0, expl: "<b>Vrai</b> : c’est une attente implicite (« le maître donne des problèmes qui ont une solution, avec juste les bonnes données »). L’« âge du capitaine » en est l’exemple célèbre." },
  { q: "Pour lutter contre les effets néfastes du contrat didactique, l’enseignant peut :", choices: ["proposer parfois des problèmes avec des données inutiles ou sans solution, et faire vérifier la vraisemblance des résultats", "donner toujours des problèmes dont toutes les données servent", "fournir l’opération à faire avec chaque énoncé", "éviter les problèmes"], answer: 0, expl: "Varier les énoncés (données superflues, manquantes, questions impossibles) oblige l’élève à <b>comprendre</b> la situation au lieu de combiner les nombres au hasard. Vérifier la vraisemblance est une étape essentielle." },
  { q: "Léa a 12 billes de plus que Tom. Ensemble, ils en ont 50. Combien de billes Tom a-t-il ?", answers: ["19", "dix-neuf"], expl: "Avec un schéma en barres : la barre de Léa = celle de Tom + 12. On retire 12 : 50 − 12 = 38 = deux barres égales, donc Tom a 38 ÷ 2 = <b>19</b> billes (et Léa 31). Vérification : 19 + 31 = 50 ✔." },
  { q: "Quel didacticien a proposé une typologie des problèmes additifs et multiplicatifs (théorie des champs conceptuels) ?", answers: ["Vergnaud", "Gérard Vergnaud", "G. Vergnaud"], expl: "Gérard <b>Vergnaud</b>. Brousseau, lui, est associé à la théorie des situations didactiques (dévolution, institutionnalisation, contrat didactique)." },
  { q: "Comment appelle-t-on un élément de la tâche que l’enseignant peut modifier et qui change les procédures des élèves ?", answers: ["variable didactique", "une variable didactique", "variables didactiques", "la variable didactique"], expl: "Une <b>variable didactique</b> : taille des nombres, présence de matériel, disposition des données… Bien la choisir permet de pousser l’élève vers la procédure visée." },
  { type: 'vf', q: "Vrai ou faux : une erreur d’élève est toujours le signe d’un manque d’attention.", answer: 1, expl: "<b>Faux</b> : beaucoup d’erreurs sont <b>logiques</b> pour l’élève et révèlent une conception (ex. un obstacle lié aux entiers). D’où la méthode : décrire, faire une hypothèse, proposer une remédiation." },
  { q: "Dans la démarche « manipuler, verbaliser, abstraire », quelle est la deuxième étape ?", answers: ["verbaliser", "la verbalisation", "verbalisation"], expl: "Après la manipulation, l’élève <b>verbalise</b> : il dit ce qu’il fait avec le vocabulaire précis (« 3 paquets de dix et 4 »), avant de passer aux écritures mathématiques." }
];
